function calendarView(){const [y,m]=month.split('-').map(Number),first=new Date(Date.UTC(y,m-1,1,15)),offset=first.getUTCDay(),start=C.addDays(month+'-01',-offset),ev=allEvents().filter(e=>(!calFilter||e.examId===calFilter)),visible=ev.filter(e=>e.start.slice(0,7)===month||(e.end&&e.start.slice(0,7)<month&&e.end.slice(0,7)>=month));return header('Tudo tem seu tempo.','Provas, inscrições, publicações e seus compromissos. Horário de Brasília.',`<div class="row">${btn(icon('download')+' Exportar .ics','export-calendar')}${btn(icon('plus'),'new-event','aria-label="Adicionar evento"')}</div>`)+`<div class="panel"><div class="panel-head"><div class="row">${btn('‹','month-prev','aria-label="Mês anterior"','small')}<h2>${fmt(month+'-01',{month:'long',year:'numeric'})}</h2>${btn('›','month-next','aria-label="Próximo mês"','small')}</div>${btn('Hoje','month-today','','small')}</div><div class="filters"><select aria-label="Filtrar objetivo" id="cal-filter" data-change="cal-filter">${options([['','Todos os objetivos'],...D.exams.map(e=>[e.id,e.shortName]),['personal','Pessoal']],calFilter)}</select>${badge('Data com fonte ≠ inscrição confirmada','amber')}</div><div class="calendar-grid">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(w=>`<div class="cal-label">${w}</div>`).join('')}${Array.from({length:42},(_,i)=>{const date=C.addDays(start,i),a=ev.filter(e=>e.start.slice(0,10)===date||(e.end&&e.start.slice(0,10)<date&&e.end.slice(0,10)>=date));return`<div class="cal-day ${date.slice(0,7)!==month?'out':''} ${date===today()?'today':''}"><span class="day-num">${Number(date.slice(8))}</span>${a.slice(0,3).map(e=>`<button class="cal-event ${e.kind}" data-action="event-detail" data-id="${e.id}" title="${esc(e.title)}">${esc(e.title)}</button>`).join('')}${a.length>3?`<span class="tiny">+${a.length-3} eventos</span>`:''}</div>`;}).join('')}</div><div class="timeline">${visible.length?visible.map(eventRow).join(''):empty('Um mês com espaço','Adicione um compromisso ou navegue até o próximo prazo.')}</div></div><div class="alert">${icon('alert')}<div><strong>22/11/2026 · TCDF + UnB</strong><br>Há sobreposição de provas à tarde. Confirme sua prioridade e os editais de convocação antes de organizar a viagem. Horários não publicados permanecem como pendentes.</div></div>`;}
